const LEGACY_RUNTIME_IDS = [
  'veloura-qv-v35-grouped-actions-runtime-2026',
  'veloura-qv-v36-glass-quick-icon-runtime-2026',
  'veloura-product-card-native-actions-sync-2026',
  'veloura-product-card-qv-v26-runtime-2026',
  'veloura-qv-v27-spacing-radius-glass-fix-2026'
];

function fail(message) { throw new Error(message); }
function exists(file) { return fs.existsSync(file); }
function count(text, needle) { return text.split(needle).length - 1; }
function escapeRegExp(value) { return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function readFile(file) {
  if (!exists(file)) fail(`Required file was not found: ${file}`);
  const raw = fs.readFileSync(file, 'utf8');
  return { text: raw.replace(/\r\n/g, '\n'), eol: raw.includes('\r\n') ? '\r\n' : '\n' };
}
function writeFile(file, text, eol) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, text.replace(/\r\n/g, '\n').replace(/\n/g, eol || '\n'), 'utf8');
}
function backupFile(file) {
  if (!exists(file)) return;
  const target = path.join(BACKUP_DIR, path.relative(ROOT, file));
  if (exists(target)) return;
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.copyFileSync(file, target);
}
function removeMarkedBlock(text, startMarker, endMarker) {
  for (;;) {
    const start = text.indexOf(startMarker);
    if (start === -1) break;
    const end = text.indexOf(endMarker, start);
    if (end === -1) fail(`Found marker without its end: ${startMarker}`);
    text = text.slice(0, start) + text.slice(end + endMarker.length);
  }
  return text;
}
function removeScriptById(text, id) {
  const pattern = new RegExp(
    '\\s*<script\\b[^>]*\\bid=["\\\']' + escapeRegExp(id) + '["\\\'][^>]*>[\\s\\S]*?<\\/script>\\s*',
    'g'
  );
  return text.replace(pattern, '\n');
}
function cleanBlankRuns(text) { return text.replace(/\n{5,}/g, '\n\n\n'); }

function updateMaster() {
  const source = readFile(MASTER_PATH);
  let text = source.text;
  [
    ['{# Veloura QV V55 direct Salla surfaces start #}', '{# Veloura QV V55 direct Salla surfaces end #}'],
    ['{# Veloura V56 safe product UI recovery start #}', '{# Veloura V56 safe product UI recovery end #}'],
    ['{# Veloura V57 unified product UI and recently viewed products start #}', '{# Veloura V57 unified product UI and recently viewed products end #}'],
    ['{# Veloura V58 stable cards and purchase surfaces start #}', '{# Veloura V58 stable cards and purchase surfaces end #}']
  ].forEach(([start, end]) => { text = removeMarkedBlock(text, start, end); });
  LEGACY_RUNTIME_IDS.forEach((id) => { text = removeScriptById(text, id); });
  text = text.replace(/\s*\{%\s*include\s+['"]partials\.veloura-product-ui-contract['"]\s*%\}\s*/g, '\n');
  const closeBody = text.lastIndexOf('</body>');
  if (closeBody === -1) fail('master.twig does not contain </body>.');
  text = text.slice(0, closeBody).trimEnd() + '\n\n' + V58_BLOCK.trim() + '\n\n' + text.slice(closeBody);
  text = cleanBlankRuns(text).trimEnd() + '\n';
  if (count(text, 'id="veloura-v58-stable-product-ui-runtime-2026"') !== 1) fail('V58 runtime was not installed exactly once.');
  LEGACY_RUNTIME_IDS.forEach((id) => { if (text.includes(`id="${id}"`)) fail(`Legacy runtime is still present: ${id}`); });
  writeFile(MASTER_PATH, text, source.eol);
}

function updateSingle() {
  const source = readFile(SINGLE_PATH);
  let text = source.text;
  [
    ['    {# Veloura V57 recently viewed settings start #}', '    {# Veloura V57 recently viewed settings end #}'],
    ['    {# Veloura V57 recently viewed products section start #}', '    {# Veloura V57 recently viewed products section end #}'],
    ['    {# Veloura V58 recently viewed settings start #}', '    {# Veloura V58 recently viewed settings end #}'],
    ['    {# Veloura V58 recently viewed products section start #}', '    {# Veloura V58 recently viewed products section end #}']
  ].forEach(([start, end]) => { text = removeMarkedBlock(text, start, end); });
  text = text.replace(/^\s*\{%\s*set\s+vpp_recent_products_(?:enabled|inherit_related)\s*=.*?%\}\s*$/gm, '');
  if (text.includes('data-veloura-recent-products')) fail('An unmarked old recently-viewed section is still present in single.twig.');

  const settingsAnchor = "    {% set vpp_related_center_title = _self.veloura_bool(theme.settings.get('veloura_related_center_title_2026', false), false)|trim == 'true' %}";
  const settingsIndex = text.indexOf(settingsAnchor);
  if (settingsIndex === -1) fail('Could not find related-products settings anchor in single.twig.');
  text = text.slice(0, settingsIndex + settingsAnchor.length) + '\n' + RECENT_SETTINGS_TWIG.trimEnd() + text.slice(settingsIndex + settingsAnchor.length);

  text = text.replace(/\s+veloura-glass-surface\b/g, '').replace(/\s+veloura-glass-sticky-product\b/g, '');
  text = text.replace(/overflow:\s*hidden\s*!important;/g, (match, offset) => {
    const area = text.slice(Math.max(0, offset - 500), offset + 100);
    return area.includes('salla-fast-checkout-button') ? 'overflow: visible !important;' : match;
  });

  const relatedPattern = /<salla-products-slider\b[\s\S]*?\bdata-veloura-related-slider\b[\s\S]*?>/;
  const relatedMatch = text.match(relatedPattern);
  if (!relatedMatch) fail('Could not find related-products slider in single.twig.');
  let relatedTag = relatedMatch[0];
  if (!/\bproduct-card-component=/.test(relatedTag)) {
    relatedTag = relatedTag.replace('<salla-products-slider', '<salla-products-slider\n                product-card-component="custom-salla-product-card"');
  } else {
    relatedTag = relatedTag.replace(/product-card-component=["'][^"']*["']/, 'product-card-component="custom-salla-product-card"');
  }
  text = text.replace(relatedMatch[0], relatedTag);

  const scriptsAnchor = '\n{% endblock %}\n\n{% block scripts %}';
  const scriptsIndex = text.lastIndexOf(scriptsAnchor);
  if (scriptsIndex === -1) fail('Could not find the final content block boundary in single.twig.');
  text = text.slice(0, scriptsIndex) + '\n' + RECENT_MARKUP.trimEnd() + text.slice(scriptsIndex);
  text = cleanBlankRuns(text).trimEnd() + '\n';
  if (count(text, 'veloura_recent_products_enabled_2026') !== 1) fail('Recently viewed enable setting is not unique.');
  if (count(text, 'data-veloura-recent-products') !== 1) fail('Recently viewed section is not unique.');
  if (!/<salla-products-slider\b[\s\S]*?product-card-component="custom-salla-product-card"[\s\S]*?data-veloura-related-slider/.test(text)) fail('Related slider custom card was not set.');
  writeFile(SINGLE_PATH, text, source.eol);
}

function updateProductCard() {
  const source = readFile(PRODUCT_CARD_PATH);
  let text = source.text;
  const eventMarker = '// Veloura V58: notify stable UI after every product-card render.';
  if (!text.includes(eventMarker)) {
    const defineNeedle = "customElements.define('custom-salla-product-card', ProductCard);";
    const defineIndex = text.indexOf(defineNeedle);
    if (defineIndex === -1) fail('Could not find custom-salla-product-card definition in product-card.js.');
    const renderClose = text.lastIndexOf('\n    }\n}', defineIndex);
    if (renderClose === -1) fail('Could not find the end of ProductCard.render() in product-card.js.');
    const eventCode = `\n      ${eventMarker}\n      this.dispatchEvent(new CustomEvent('veloura:product-card-rendered', {\n        bubbles: true,\n        composed: true\n      }));`;
    text = text.slice(0, renderClose) + eventCode + text.slice(renderClose);
  }

  const observerStart = '    /* Veloura V58 targeted quick-view observer start */';
  if (!text.includes(observerStart)) {
    const oldObserver = /\s{4}const observer = new MutationObserver\(scanCards\);\n\s{4}observer\.observe\(document\.body, \{\n\s{6}childList: true,\n\s{6}subtree: true\n\s{4}\}\);/;
    const targeted = `    /* Veloura V58 targeted quick-view observer start */\n    function scanQuickViewAddedNode(node) {\n      if (!node || node.nodeType !== 1) return;\n      const selector = 'product-card,custom-salla-product-card,.s-product-card-entry';\n      const direct = node.matches && node.matches(selector) ? node : null;\n      const owner = !direct && node.closest ? node.closest(selector) : null;\n      if (direct) injectButton(direct);\n      else if (owner) injectButton(owner);\n      if (node.querySelectorAll) node.querySelectorAll(selector).forEach(injectButton);\n    }\n\n    const observer = new MutationObserver(function (mutations) {\n      mutations.forEach(function (mutation) {\n        mutation.addedNodes.forEach(scanQuickViewAddedNode);\n      });\n    });\n    observer.observe(document.body, { childList: true, subtree: true });\n    /* Veloura V58 targeted quick-view observer end */`;
    if (!oldObserver.test(text)) fail('Could not find the legacy quick-view observer in product-card.js.');
    text = text.replace(oldObserver, '\n' + targeted);
  }
  if (count(text, eventMarker) !== 1) fail('Product-card render event is not unique.');
  if (count(text, observerStart) !== 1) fail('Targeted quick-view observer is not unique.');
  writeFile(PRODUCT_CARD_PATH, text.trimEnd() + '\n', source.eol);
}

function updateTwilight() {
  const source = readFile(TWILIGHT_PATH);
  let data;
  try { data = JSON.parse(source.text); } catch (error) { fail(`twilight.json is invalid before installation: ${error.message}`); }
  if (!Array.isArray(data.settings)) fail('twilight.json does not contain a settings array.');
  const ids = new Set(RECENT_SETTINGS_JSON.map((item) => item.id));
  data.settings = data.settings.filter((item) => !item || !ids.has(item.id));
  const anchorIndex = data.settings.findIndex((item) => item && item.id === 'veloura_related_center_title_2026');
  if (anchorIndex === -1) fail('Could not find veloura_related_center_title_2026 in twilight.json.');
  data.settings.splice(anchorIndex + 1, 0, ...RECENT_SETTINGS_JSON);
  RECENT_SETTINGS_JSON.forEach((wanted) => {
    if (data.settings.filter((item) => item && item.id === wanted.id).length !== 1) fail(`Duplicated setting: ${wanted.id}`);
  });
  const out = JSON.stringify(data, null, 2) + '\n';
  JSON.parse(out);
  writeFile(TWILIGHT_PATH, out, source.eol);
}
function removeUnsafePartial() { if (exists(UNSAFE_PARTIAL_PATH)) fs.rmSync(UNSAFE_PARTIAL_PATH, { force: true }); }

function main() {
  [MASTER_PATH, SINGLE_PATH, PRODUCT_CARD_PATH, TWILIGHT_PATH].forEach((file) => {
    if (!exists(file)) fail(`Run this installer from the theme root. Missing: ${file}`);
  });
  fs.mkdirSync(BACKUP_DIR, { recursive: true });
  [MASTER_PATH, SINGLE_PATH, PRODUCT_CARD_PATH, TWILIGHT_PATH, UNSAFE_PARTIAL_PATH].forEach(backupFile);
  updateMaster();
  updateSingle();
  updateProductCard();
  updateTwilight();
  removeUnsafePartial();
  console.log('');
  console.log('Veloura V58 stable product UI was installed successfully.');
  console.log('Removed the conflicting card observers that caused button movement and repeated updates.');
  console.log('Fixed first-load card initialization, normal/sticky glass isolation, purchase buttons, and recently viewed cards.');
  console.log('');
  console.log('Now run: node .\\VERIFY-VELOURA-V58.js');
}
try { main(); } catch (error) {
  console.error('');
  console.error('V58 INSTALLATION FAILED');
  console.error(error && error.stack ? error.stack : error);
  process.exit(1);
}
